const lead = $('Normalize input').first().json;
let q = { priority: 'warm', summary: 'Не удалось разобрать ответ модели', next_step: 'Проверить заявку вручную' };
try {
  q = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {}
const icon = { hot: '🔥', warm: '🟡', cold: '❄️' }[q.priority] || '🟡';
const text = `${icon} Новая заявка (${q.priority})\n` +
  `Имя: ${lead.name || '—'}\nТелефон: ${lead.phone || '—'}\nИсточник: ${lead.source}\n\n` +
  `${q.summary}\nСледующий шаг: ${q.next_step}`;
return [{ json: { text, priority: q.priority } }];
